// The Depth Anything V2 DPT head of FoundationStereo's DINOv2 branch (`DPTHead`,
// `use_clstoken=False`) up to `out`, and `Feature`'s resize of it to `vit_feat`,
// against PyTorch in FP64.
//
// Reduced width (ViT 64, features 32, out_channels 16/32/64/64) with seeded random
// weights, on 5x7 patch grids. Fixtures generated by tests/fixtures/dpt/generate.py.
//
// Runs on whichever backend teeny-runtime was built for: CUDA, or RISC-V under qemu
// (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use teeny_core::name_scope::name_scope;
use vision_rs::models::stereo::feature::dpt::{DptDims, dpt_head, vit_feat};

/// The head on four 5x7 patch grids (`out` 70x98), then `vit_feat` at 17x25.
#[test]
#[serial]
fn dpt_head_matches_pytorch() -> anyhow::Result<()> {
    let dims = DptDims {
        vit: 64,
        features: 32,
        out_channels: [16, 32, 64, 64],
        patch: 14,
    };
    let grid: &[usize] = &[1, 64, 5, 7];
    check_block(
        "dpt/dpt_small",
        "dpt/dpt_small",
        &[("l0", grid), ("l1", grid), ("l2", grid), ("l3", grid)],
        |i| {
            let out = {
                let _g = name_scope("depth_head");
                dpt_head::<f32>(
                    &dims,
                    &[i[0].clone(), i[1].clone(), i[2].clone(), i[3].clone()],
                    (5, 7),
                )
            };
            let feat = vit_feat::<f32>(&out, (17, 25));
            vec![("out", out), ("vit_feat", feat)]
        },
        1e-4,
    )?;
    Ok(())
}

/// The head with a real FoundationStereo checkpoint's
/// `feature.dino.depth_anything.depth_head` weights, on the real ViT-L patch grids
/// (16x24) of the sample left image, then `vit_feat` at 56x80, against PyTorch in
/// FP64. `out` reaches ~1700, so the tolerance is absolute 2e-2 (~1e-5 relative).
/// Build the fixtures with tests/fixtures/dpt/gen_real.py, point `FS_REAL_FIXTURES` at
/// the directory holding `dpt_real/` and run with `--ignored`.
#[test]
#[serial]
#[ignore = "needs FS_REAL_FIXTURES (real-checkpoint fixtures, not committed)"]
fn dpt_head_matches_real_checkpoint() -> anyhow::Result<()> {
    let root = std::env::var("FS_REAL_FIXTURES")
        .expect("set FS_REAL_FIXTURES to the real-checkpoint fixture directory");
    let dir = format!("{root}/dpt_real");
    let dims = DptDims::vitl();
    let grid: &[usize] = &[1, 1024, 16, 24];
    check_block(
        "dpt_real",
        &dir,
        &[("l0", grid), ("l1", grid), ("l2", grid), ("l3", grid)],
        |i| {
            let out = {
                let _g = name_scope("depth_head");
                dpt_head::<f32>(
                    &dims,
                    &[i[0].clone(), i[1].clone(), i[2].clone(), i[3].clone()],
                    (16, 24),
                )
            };
            let feat = vit_feat::<f32>(&out, (56, 80));
            vec![("out", out), ("vit_feat", feat)]
        },
        2e-2,
    )?;
    Ok(())
}
